                if points[end][1] > points[start][1]:
                    dp[start][end] += (topmost[end] - bottommost[start] + 1) % MOD
                dp[start][end] %= MOD

    result = 0
    for i in range(N):
        for j in range(i, N):
            result = (result + dp[i][j]) % MOD

    print(result)

